SELECT COUNT(*) AS fact_cnt, MIN(fiscal_year) AS min_year, MAX(fiscal_year) AS max_year
FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact
WHERE cik = '1318605' AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax');

SELECT *
FROM SHOW DQ ALL INVALID TABLE lightning.metastore.explainwhy.explainwhy_usl.revenue_fact
WHERE cik = '1318605' AND fiscal_year < 2011;

SELECT MIN(filed_date) AS first_filing, MIN(fiscal_year) AS first_fiscal_year
FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact
WHERE cik = '1318605' AND form_type IN ('10-K','10-Q');
